cat > agent_tools/addver.py <<'PYEOF'
import re, sys, os

TSV = '/workspace/utils/list-versions/version_date.tsv'

def key(tag):
    m = re.match(r'v(\d+)\.(\d+)\.(\d+)\.(\d+)', tag)
    return tuple(int(x) for x in m.groups())

def add(tag, date):
    lines = open(TSV).read().splitlines()
    for l in lines:
        if l.split('\t')[0] == tag:
            return False
    k = key(tag)
    out = []
    inserted = False
    for l in lines:
        if not inserted and key(l.split('\t')[0]) < k:
            out.append(f'{tag}\t{date}')
            inserted = True
        out.append(l)
    if not inserted:
        out.append(f'{tag}\t{date}')
    open(TSV, 'w').write('\n'.join(out) + '\n')
    return True

if __name__ == '__main__':
    print(add(sys.argv[1], sys.argv[2]))
