int ColumnAggregateFunction::compareAt(size_t n, size_t m, const IColumn & rhs, int) const
{
    const auto & rhs_column = assert_cast<const ColumnAggregateFunction &>(rhs);

    /// The states of two different aggregate functions are never equal.
    if (const int name_diff = func->getName().compare(rhs_column.func->getName()); name_diff != 0)
